






























































import Modal from '@/components/Modal.vue'
import { defineComponent } from '@vue/composition-api'

export default defineComponent({
    props : {
        receipt : Object,
        show : Boolean
    },
    components : {
        Modal
    },
    setup(props, {emit}){

        function Cancel(){
            emit('Cancel')
        }

        return {
            Cancel  
        }
    }
})
